var r=[{title:`Συνηθισμένοι τύποι μεταφορών`,text:`Η μεταφορά του αγρότη (farmer’s carry) χρησιμοποιεί ένα βάρος σε κάθε χέρι. Η μεταφορά βαλίτσας (suitcase carry) χρησιμοποιεί ένα βάρος στη μία πλευρά, οπότε ο κορμός σας πρέπει να αντιστέκεται στην πλάγια κάμψη. Η μπροστινή μεταφορά κρατά το φορτίο κοντά στο στήθος σας, και η μεταφορά πάνω από το κεφάλι ζητά περισσότερα από τη σταθερότητα των ώμων και χρειάζεται περισσότερο ύψος. Κάθε θέση αλλάζει τους μυς και τη δεξιότητα που εμπλέκονται.`},{title:`Βασική τεχνική`,text:`Διαλέξτε ένα φορτίο που μπορείτε να κρατήσετε με ασφάλεια σε όλη τη διαδρομή, σταθείτε ψηλά σε άνετη στάση και περπατήστε με σκόπιμα βήματα. Κρατήστε το βάρος ασφαλές, μη γέρνετε πολύ προς αυτό ή μακριά του, και συνεχίστε να αναπνέετε σε μια μεγάλη διαδρομή. Επιβραδύνετε όταν στρίβετε και κρατήστε τη διαδρομή σας ελεύθερη.`},{title:`Πώς να δοσολογείτε τις μεταφορές`,text:`Μετράτε τις μεταφορές με απόσταση ή χρόνο αντί για επαναλήψεις. Για παράδειγμα, μεταφέρετε δύο αλτήρες που μπορείτε να κρατάτε σταθερά για 20–30 δευτερόλεπτα, ξεκουραστείτε και επαναλάβετε. Όταν η λαβή και η στάση σας μένουν ίδιες, προσθέστε λίγη απόσταση, χρόνο ή βάρος. Ένα βαρύτερο βάρος δεν βοηθά αν κάνει τα βήματά σας βιαστικά και άνισα.`},{title:`Χώρος και ασφάλεια`,text:`Ελέγξτε ότι η διαδρομή σας έχει αρκετό ελεύθερο δάπεδο, αντιολισθητική επιφάνεια και κανέναν άνθρωπο ή αντικείμενο στον δρόμο. Αφήστε τα βάρη κάτω με έλεγχο και μην τα ρίχνετε. Παραλείψτε τις μεταφορές πάνω από το κεφάλι κάτω από χαμηλό ταβάνι ή όταν δεν είστε σίγουροι για τον έλεγχο των ώμων σας. Προπονείτε πάντα τις μονόπλευρες μεταφορές και στις δύο πλευρές.`},{title:`Χρήση του TrainUp`,text:`Οι μεταφορές μπορούν να καλύψουν μια θέση δύναμης όταν έχετε τον εξοπλισμό και τον χώρο για να περπατήσετε. Το πρόγραμμά σας ελέγχει το μέγεθος του δαπέδου που ορίσατε στο Profile. Αν η πλάτη ή τα χέρια σας περιορίζουν πόσο φορτίο στη σπονδυλική στήλη ή πόση εργασία λαβής αντέχετε, προσθέστε αυτή την περιοχή του σώματος ως περιορισμό στο Profile ώστε το πρόγραμμα να παραλείπει ασκήσεις που δεν ταιριάζουν.`}];var s=[{label:`Βιβλιοθήκη ασκήσεων του ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: ασφάλεια και βασικές αρχές της προπόνησης με αντίσταση`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var i={sections:r,sources:s};export{i as default,r as sections,s as sources};